var data = {lines:[
{"lineNum":"    1","line":"#!/usr/bin/env bash"},
{"lineNum":"    2","line":"#"},
{"lineNum":"    3","line":"# nopasswd-sudo.sh — toggle temporary passwordless sudo for a user."},
{"lineNum":"    4","line":"#"},
{"lineNum":"    5","line":"# Handy during migration/maintenance sessions that run many sudo commands"},
{"lineNum":"    6","line":"# non-interactively (e.g. driven over SSH). Turn it ON at the start, OFF when"},
{"lineNum":"    7","line":"# done. The drop-in is validated with `visudo` before being installed, so a"},
{"lineNum":"    8","line":"# typo can\'t lock you out of sudo."},
{"lineNum":"    9","line":"#"},
{"lineNum":"   10","line":"# Enabling also arms an auto-revoke so you can never leave passwordless sudo on"},
{"lineNum":"   11","line":"# by accident: an in-session timer switches it OFF after the timeout (default"},
{"lineNum":"   12","line":"# 30 min; pass a different number of minutes, or 0 to disable), AND a persistent"},
{"lineNum":"   13","line":"# boot-time unit clears it on every reboot. The in-session timer is transient"},
{"lineNum":"   14","line":"# and does NOT survive a reboot, so the boot unit is the reboot safety net —"},
{"lineNum":"   15","line":"# without it, a reboot would strand the grant with nothing left to revoke it."},
{"lineNum":"   16","line":"#"},
{"lineNum":"   17","line":"# Usage:"},
{"lineNum":"   18","line":"#   sudo ./nopasswd-sudo.sh on   [user] [minutes]   # default user: $SUDO_USER, default 30 min"},
{"lineNum":"   19","line":"#   sudo ./nopasswd-sudo.sh off"},
{"lineNum":"   20","line":"#   sudo ./nopasswd-sudo.sh status"},
{"lineNum":"   21","line":"#"},
{"lineNum":"   22","line":"set -o errexit","class":"lineCov","hits":"1","order":"3710",},
{"lineNum":"   23","line":"set -o nounset","class":"lineCov","hits":"1","order":"3719",},
{"lineNum":"   24","line":"set -o pipefail","class":"lineCov","hits":"1","order":"3706",},
{"lineNum":"   25","line":""},
{"lineNum":"   26","line":"# shellcheck source=../../lib/core.sh"},
{"lineNum":"   27","line":"source \"$(cd \"$(dirname \"$0\")\" && pwd -P)/../../lib/core.sh\"","class":"lineCov","hits":"1","order":"3726",},
{"lineNum":"   28","line":"# @include ../../lib/core.sh"},
{"lineNum":"   29","line":""},
{"lineNum":"   30","line":"# The two paths this writes to are taken from the environment when set. Both are system-wide and one of"},
{"lineNum":"   31","line":"# them governs sudo itself, so being able to point them elsewhere is what allows the grant, the revoke and"},
{"lineNum":"   32","line":"# the boot unit to be exercised without touching a real machine\'s sudoers; unset, they are the real ones."},
{"lineNum":"   33","line":": \"${DROPIN:=/etc/sudoers.d/99-temp-nopasswd}\"","class":"lineCov","hits":"1","order":"3727",},
{"lineNum":"   34","line":": \"${SYSTEMD_UNIT_DIR:=/etc/systemd/system}\"","class":"lineCov","hits":"1","order":"3713",},
{"lineNum":"   35","line":"readonly DROPIN SYSTEMD_UNIT_DIR","class":"lineCov","hits":"1","order":"3714",},
{"lineNum":"   36","line":"readonly AUTO_UNIT=\"nopasswd-sudo-autorevoke\"","class":"lineCov","hits":"1","order":"3721",},
{"lineNum":"   37","line":"readonly BOOT_UNIT=\"nopasswd-sudo-bootrevoke\"","class":"lineCov","hits":"1","order":"3722",},
{"lineNum":"   38","line":"readonly DEFAULT_TIMEOUT_MIN=30","class":"lineCov","hits":"1","order":"3729",},
{"lineNum":"   39","line":""},
{"lineNum":"   40","line":"#######################################"},
{"lineNum":"   41","line":"# Log an informational message to stdout."},
{"lineNum":"   42","line":"#######################################"},
{"lineNum":"   43","line":""},
{"lineNum":"   44","line":"#######################################"},
{"lineNum":"   45","line":"# Print usage information."},
{"lineNum":"   46","line":"#######################################"},
{"lineNum":"   47","line":"show_usage() {"},
{"lineNum":"   48","line":"  cat <<EOF","class":"lineCov","hits":"1","order":"3718",},
{"lineNum":"   49","line":"Usage: sudo $(basename \"$0\") {on|off|status} [user] [minutes]"},
{"lineNum":"   50","line":""},
{"lineNum":"   51","line":"  on [user] [minutes]   grant passwordless sudo (default user: \\${SUDO_USER:-root})"},
{"lineNum":"   52","line":"                        and arm auto-revoke after [minutes] (default ${DEFAULT_TIMEOUT_MIN}; 0 = never)"},
{"lineNum":"   53","line":"  off                   revoke it now (removes ${DROPIN}, cancels the timer)"},
{"lineNum":"   54","line":"  status                show whether it is enabled and any armed auto-revoke"},
{"lineNum":"   55","line":"  --version             show the version and exit"},
{"lineNum":"   56","line":""},
{"lineNum":"   57","line":"Examples:"},
{"lineNum":"   58","line":"  sudo $(basename \"$0\") on            # enable for \\$SUDO_USER, auto-off in ${DEFAULT_TIMEOUT_MIN} min"},
{"lineNum":"   59","line":"  sudo $(basename \"$0\") on 90         # enable for \\$SUDO_USER, auto-off in 90 min"},
{"lineNum":"   60","line":"  sudo $(basename \"$0\") on jure 0     # enable for jure, no auto-revoke"},
{"lineNum":"   61","line":"EOF"},
{"lineNum":"   62","line":"}"},
{"lineNum":"   63","line":""},
{"lineNum":"   64","line":"#######################################"},
{"lineNum":"   65","line":"# Abort unless running as root."},
{"lineNum":"   66","line":"#######################################"},
{"lineNum":"   67","line":"require_root() {"},
{"lineNum":"   68","line":"  if [[ \"${EUID}\" -ne 0 ]]; then","class":"lineCov","hits":"1","order":"3732",},
{"lineNum":"   69","line":"    log_error \"must run as root (use sudo).\"","class":"lineNoCov","hits":"0",},
{"lineNum":"   70","line":"    exit 1","class":"lineNoCov","hits":"0",},
{"lineNum":"   71","line":"  fi"},
{"lineNum":"   72","line":"}"},
{"lineNum":"   73","line":""},
{"lineNum":"   74","line":"#######################################"},
{"lineNum":"   75","line":"# Enable passwordless sudo for a user via a validated sudoers drop-in."},
{"lineNum":"   76","line":"# Globals:"},
{"lineNum":"   77","line":"#   DROPIN"},
{"lineNum":"   78","line":"# Arguments:"},
{"lineNum":"   79","line":"#   Target user (defaults to ${SUDO_USER})."},
{"lineNum":"   80","line":"#######################################"},
{"lineNum":"   81","line":"enable_nopasswd() {"},
{"lineNum":"   82","line":"  local user=\"${1:-${SUDO_USER:-}}\"","class":"lineCov","hits":"1","order":"3720",},
{"lineNum":"   83","line":"  if [[ -z \"${user}\" ]]; then","class":"lineCov","hits":"1","order":"3705",},
{"lineNum":"   84","line":"    log_error \"could not determine target user; pass one explicitly.\"","class":"lineCov","hits":"1","order":"3703",},
{"lineNum":"   85","line":"    exit 1","class":"lineCov","hits":"1","order":"3724",},
{"lineNum":"   86","line":"  fi"},
{"lineNum":"   87","line":"  if ! id -u \"${user}\" >/dev/null 2>&1; then","class":"lineCov","hits":"1","order":"3701",},
{"lineNum":"   88","line":"    log_error \"no such user: ${user}\"","class":"lineCov","hits":"1","order":"3700",},
{"lineNum":"   89","line":"    exit 1","class":"lineCov","hits":"1","order":"3699",},
{"lineNum":"   90","line":"  fi"},
{"lineNum":"   91","line":""},
{"lineNum":"   92","line":"  local tmp","class":"lineCov","hits":"1","order":"3728",},
{"lineNum":"   93","line":"  tmp=\"$(mktemp)\"","class":"lineCov","hits":"1","order":"3712",},
{"lineNum":"   94","line":"  printf \'%s ALL=(ALL) NOPASSWD:ALL\\n\' \"${user}\" >\"${tmp}\"","class":"lineCov","hits":"1","order":"3716",},
{"lineNum":"   95","line":""},
{"lineNum":"   96","line":"  # Validate BEFORE installing — a bad sudoers file can lock you out of sudo."},
{"lineNum":"   97","line":"  if ! visudo -cf \"${tmp}\" >/dev/null; then","class":"lineCov","hits":"1","order":"3730",},
{"lineNum":"   98","line":"    rm -f \"${tmp}\"","class":"lineCov","hits":"1","order":"3735",},
{"lineNum":"   99","line":"    log_error \"sudoers syntax check failed; not installing.\"","class":"lineCov","hits":"1","order":"3708",},
{"lineNum":"  100","line":"    exit 1","class":"lineCov","hits":"1","order":"3698",},
{"lineNum":"  101","line":"  fi"},
{"lineNum":"  102","line":""},
{"lineNum":"  103","line":"  install -m 0440 -o root -g root \"${tmp}\" \"${DROPIN}\"","class":"lineCov","hits":"1","order":"3697",},
{"lineNum":"  104","line":"  rm -f \"${tmp}\"","class":"lineCov","hits":"1","order":"3737",},
{"lineNum":"  105","line":"  log_info \"passwordless sudo ENABLED for \'${user}\' (${DROPIN}).\"","class":"lineCov","hits":"1","order":"3738",},
{"lineNum":"  106","line":"}"},
{"lineNum":"  107","line":""},
{"lineNum":"  108","line":"#######################################"},
{"lineNum":"  109","line":"# Arm a one-shot systemd timer that runs `off` after the timeout."},
{"lineNum":"  110","line":"# A transient timer is used so it survives this script (and the SSH session)"},
{"lineNum":"  111","line":"# exiting. Re-arming first cancels any existing timer, resetting the clock."},
{"lineNum":"  112","line":"# Globals:"},
{"lineNum":"  113","line":"#   AUTO_UNIT"},
{"lineNum":"  114","line":"# Arguments:"},
{"lineNum":"  115","line":"#   Timeout in minutes (0 disables auto-revoke)."},
{"lineNum":"  116","line":"#######################################"},
{"lineNum":"  117","line":"schedule_revoke() {"},
{"lineNum":"  118","line":"  local minutes=\"${1}\"","class":"lineCov","hits":"1","order":"3739",},
{"lineNum":"  119","line":"  cancel_revoke","class":"lineCov","hits":"1","order":"3740",},
{"lineNum":"  120","line":"  if [[ \"${minutes}\" -eq 0 ]]; then","class":"lineCov","hits":"1","order":"3741",},
{"lineNum":"  121","line":"    log_info \"auto-revoke DISABLED (timeout 0) — remember to run \'off\' yourself.\"","class":"lineCov","hits":"1","order":"3743",},
{"lineNum":"  122","line":"    return","class":"lineCov","hits":"1","order":"3745",},
{"lineNum":"  123","line":"  fi"},
{"lineNum":"  124","line":"  local self","class":"lineCov","hits":"1","order":"3748",},
{"lineNum":"  125","line":"  self=\"$(readlink -f \"$0\")\"","class":"lineCov","hits":"1","order":"3750",},
{"lineNum":"  126","line":"  local -a args=(--quiet --unit=\"${AUTO_UNIT}\" --on-active=\"${minutes}min\")","class":"lineCov","hits":"1","order":"3751",},
{"lineNum":"  127","line":"  args+=(--description=\"Auto-revoke temporary passwordless sudo\")","class":"lineCov","hits":"1","order":"3733",},
{"lineNum":"  128","line":"  args+=(\"${self}\" off)","class":"lineCov","hits":"1","order":"3736",},
{"lineNum":"  129","line":"  systemd-run \"${args[@]}\"","class":"lineCov","hits":"1","order":"3709",},
{"lineNum":"  130","line":"  log_info \"auto-revoke ARMED: passwordless sudo self-disables in ${minutes} min.\"","class":"lineCov","hits":"1","order":"3753",},
{"lineNum":"  131","line":"}"},
{"lineNum":"  132","line":""},
{"lineNum":"  133","line":"#######################################"},
{"lineNum":"  134","line":"# Cancel any pending auto-revoke timer (idempotent)."},
{"lineNum":"  135","line":"# Globals:"},
{"lineNum":"  136","line":"#   AUTO_UNIT"},
{"lineNum":"  137","line":"#######################################"},
{"lineNum":"  138","line":"cancel_revoke() {"},
{"lineNum":"  139","line":"  systemctl stop \"${AUTO_UNIT}.timer\" >/dev/null 2>&1 || true","class":"lineCov","hits":"1","order":"3754",},
{"lineNum":"  140","line":"  systemctl reset-failed \"${AUTO_UNIT}.service\" \"${AUTO_UNIT}.timer\" >/dev/null 2>&1 || true","class":"lineCov","hits":"1","order":"3711",},
{"lineNum":"  141","line":"}"},
{"lineNum":"  142","line":""},
{"lineNum":"  143","line":"#######################################"},
{"lineNum":"  144","line":"# Install and enable a persistent boot-time unit that revokes passwordless"},
{"lineNum":"  145","line":"# sudo on every boot. The in-session auto-revoke timer is transient and does"},
{"lineNum":"  146","line":"# NOT survive a reboot, so without this a reboot could strand the grant with"},
{"lineNum":"  147","line":"# nothing left to remove it. Idempotent; safe to leave enabled permanently"},
{"lineNum":"  148","line":"# (its `off` is a no-op when no drop-in is present)."},
{"lineNum":"  149","line":"# Globals:"},
{"lineNum":"  150","line":"#   BOOT_UNIT"},
{"lineNum":"  151","line":"#######################################"},
{"lineNum":"  152","line":"ensure_boot_revoke() {"},
{"lineNum":"  153","line":"  local self unit=\"${SYSTEMD_UNIT_DIR}/${BOOT_UNIT}.service\"","class":"lineCov","hits":"1","order":"3717",},
{"lineNum":"  154","line":"  self=\"$(readlink -f \"$0\")\"","class":"lineCov","hits":"1","order":"3725",},
{"lineNum":"  155","line":"  if [[ ! -f \"${unit}\" ]]; then","class":"lineCov","hits":"1","order":"3723",},
{"lineNum":"  156","line":"    cat >\"${unit}\" <<UNIT","class":"lineCov","hits":"1","order":"3731",},
{"lineNum":"  157","line":"[Unit]"},
{"lineNum":"  158","line":"Description=Revoke temporary passwordless sudo on boot"},
{"lineNum":"  159","line":"After=local-fs.target"},
{"lineNum":"  160","line":""},
{"lineNum":"  161","line":"[Service]"},
{"lineNum":"  162","line":"Type=oneshot"},
{"lineNum":"  163","line":"ExecStart=${self} off"},
{"lineNum":"  164","line":""},
{"lineNum":"  165","line":"[Install]"},
{"lineNum":"  166","line":"WantedBy=multi-user.target"},
{"lineNum":"  167","line":"UNIT"},
{"lineNum":"  168","line":"    systemctl daemon-reload","class":"lineCov","hits":"1","order":"3756",},
{"lineNum":"  169","line":"  fi"},
{"lineNum":"  170","line":"  systemctl enable \"${BOOT_UNIT}.service\" >/dev/null 2>&1 || true","class":"lineCov","hits":"1","order":"3757",},
{"lineNum":"  171","line":"}"},
{"lineNum":"  172","line":""},
{"lineNum":"  173","line":"#######################################"},
{"lineNum":"  174","line":"# Remove the passwordless sudo drop-in and cancel the auto-revoke timer."},
{"lineNum":"  175","line":"# Globals:"},
{"lineNum":"  176","line":"#   DROPIN"},
{"lineNum":"  177","line":"#######################################"},
{"lineNum":"  178","line":"disable_nopasswd() {"},
{"lineNum":"  179","line":"  if [[ -f \"${DROPIN}\" ]]; then","class":"lineCov","hits":"1","order":"3742",},
{"lineNum":"  180","line":"    rm -f \"${DROPIN}\"","class":"lineCov","hits":"1","order":"3744",},
{"lineNum":"  181","line":"    log_info \"passwordless sudo DISABLED (removed ${DROPIN}).\"","class":"lineCov","hits":"1","order":"3746",},
{"lineNum":"  182","line":"  else"},
{"lineNum":"  183","line":"    log_info \"already disabled (no ${DROPIN}).\"","class":"lineCov","hits":"1","order":"3749",},
{"lineNum":"  184","line":"  fi"},
{"lineNum":"  185","line":"  cancel_revoke","class":"lineCov","hits":"1","order":"3752",},
{"lineNum":"  186","line":"}"},
{"lineNum":"  187","line":""},
{"lineNum":"  188","line":"#######################################"},
{"lineNum":"  189","line":"# Report whether the drop-in is present and whether auto-revoke is armed."},
{"lineNum":"  190","line":"# Globals:"},
{"lineNum":"  191","line":"#   DROPIN"},
{"lineNum":"  192","line":"#   AUTO_UNIT"},
{"lineNum":"  193","line":"#   BOOT_UNIT"},
{"lineNum":"  194","line":"#######################################"},
{"lineNum":"  195","line":"show_status() {"},
{"lineNum":"  196","line":"  if [[ -f \"${DROPIN}\" ]]; then","class":"lineCov","hits":"1","order":"3758",},
{"lineNum":"  197","line":"    log_info \"ENABLED:\"","class":"lineCov","hits":"1","order":"3759",},
{"lineNum":"  198","line":"    sed \'s/^/  /\' \"${DROPIN}\"","class":"lineCov","hits":"1","order":"3755",},
{"lineNum":"  199","line":"  else"},
{"lineNum":"  200","line":"    log_info \"DISABLED (no ${DROPIN}).\"","class":"lineCov","hits":"1","order":"3695",},
{"lineNum":"  201","line":"  fi"},
{"lineNum":"  202","line":"  if systemctl is-active --quiet \"${AUTO_UNIT}.timer\" 2>/dev/null; then","class":"lineCov","hits":"1","order":"3694",},
{"lineNum":"  203","line":"    log_info \"auto-revoke (this session): ARMED\"","class":"lineCov","hits":"1","order":"3693",},
{"lineNum":"  204","line":"    local timers","class":"lineCov","hits":"1","order":"3692",},
{"lineNum":"  205","line":"    timers=$(systemctl list-timers \"${AUTO_UNIT}.timer\" --no-pager 2>/dev/null || true)","class":"lineCov","hits":"1","order":"3691",},
{"lineNum":"  206","line":"    sed -n \'2p\' <<<\"${timers}\" | sed \'s/^/  /\'","class":"lineCov","hits":"1","order":"3690",},
{"lineNum":"  207","line":"  else"},
{"lineNum":"  208","line":"    log_info \"auto-revoke (this session): not armed\"","class":"lineCov","hits":"1","order":"3689",},
{"lineNum":"  209","line":"  fi"},
{"lineNum":"  210","line":"  if systemctl is-enabled --quiet \"${BOOT_UNIT}.service\" 2>/dev/null; then","class":"lineCov","hits":"1","order":"3704",},
{"lineNum":"  211","line":"    log_info \"boot-revoke: enabled (passwordless sudo is cleared on every reboot)\"","class":"lineCov","hits":"1","order":"3702",},
{"lineNum":"  212","line":"  else"},
{"lineNum":"  213","line":"    log_info \"boot-revoke: NOT installed (a reboot would not clear a stale grant)\"","class":"lineCov","hits":"1","order":"3688",},
{"lineNum":"  214","line":"  fi"},
{"lineNum":"  215","line":"}"},
{"lineNum":"  216","line":""},
{"lineNum":"  217","line":"#######################################"},
{"lineNum":"  218","line":"# Entry point: dispatch on the requested action."},
{"lineNum":"  219","line":"#######################################"},
{"lineNum":"  220","line":"main() {"},
{"lineNum":"  221","line":"  case \"${1:-}\" in","class":"lineCov","hits":"1","order":"3715",},
{"lineNum":"  222","line":"    -h | --help | \"\") show_usage; exit 0 ;;","class":"lineCov","hits":"1","order":"3687",},
{"lineNum":"  223","line":"    --version)        show_version; exit 0 ;;","class":"lineCov","hits":"1","order":"6866",},
{"lineNum":"  224","line":"  esac"},
{"lineNum":"  225","line":"  require_root","class":"lineCov","hits":"1","order":"3734",},
{"lineNum":"  226","line":"  case \"${1}\" in","class":"lineCov","hits":"1","order":"3707",},
{"lineNum":"  227","line":"    on)"},
{"lineNum":"  228","line":"      # on [user] [minutes]; a bare numeric first arg is treated as minutes."},
{"lineNum":"  229","line":"      local user=\"\" minutes=\"${DEFAULT_TIMEOUT_MIN}\"","class":"lineCov","hits":"1","order":"3686",},
{"lineNum":"  230","line":"      if [[ \"${2:-}\" =~ ^[0-9]+$ ]]; then","class":"lineCov","hits":"1","order":"3696",},
{"lineNum":"  231","line":"        minutes=\"${2}\"","class":"lineCov","hits":"1","order":"6867",},
{"lineNum":"  232","line":"      else"},
{"lineNum":"  233","line":"        user=\"${2:-}\"","class":"lineCov","hits":"1","order":"3685",},
{"lineNum":"  234","line":"        [[ \"${3:-}\" =~ ^[0-9]+$ ]] && minutes=\"${3}\"","class":"lineCov","hits":"1","order":"3684",},
{"lineNum":"  235","line":"      fi"},
{"lineNum":"  236","line":"      # Install the boot-time safety net BEFORE granting, so a reboot can never"},
{"lineNum":"  237","line":"      # strand the grant even if everything after this point fails."},
{"lineNum":"  238","line":"      ensure_boot_revoke","class":"lineCov","hits":"1","order":"3683",},
{"lineNum":"  239","line":"      enable_nopasswd \"${user}\"","class":"lineCov","hits":"1","order":"3682",},
{"lineNum":"  240","line":"      schedule_revoke \"${minutes}\"","class":"lineCov","hits":"1","order":"3681",},
{"lineNum":"  241","line":"      ;;"},
{"lineNum":"  242","line":"    off)    disable_nopasswd ;;","class":"lineCov","hits":"1","order":"3680",},
{"lineNum":"  243","line":"    status) show_status ;;","class":"lineNoCov","hits":"0",},
{"lineNum":"  244","line":"    *)      log_error \"unknown command: ${1}\"; show_usage; exit 2 ;;","class":"lineCov","hits":"1","order":"3679",},
{"lineNum":"  245","line":"  esac"},
{"lineNum":"  246","line":"}"},
{"lineNum":"  247","line":""},
{"lineNum":"  248","line":"# Only run when executed, not when sourced — the test suite sources this file to exercise its"},
{"lineNum":"  249","line":"# individual functions."},
{"lineNum":"  250","line":"if [[ \"${BASH_SOURCE[0]}\" == \"${0}\" ]]; then","class":"lineCov","hits":"1","order":"3678",},
{"lineNum":"  251","line":"  main \"$@\"","class":"lineCov","hits":"1","order":"3747",},
{"lineNum":"  252","line":"fi"},
]};
